"""Resolve .ai-log/session.jsonl merge conflict as a union, minus already-archived lines."""

import glob
import hashlib
import io
import json
import os

LOG = ".ai-log/session.jsonl"
MARKERS = ("<<<<<<<", "=======", ">>>>>>>", "|||||||")


def h(line):
    return hashlib.sha1(line.encode("utf-8", "replace")).hexdigest()


def read_lines(path):
    with io.open(path, encoding="utf-8", errors="replace") as f:
        return [ln.rstrip("\n").rstrip("\r") for ln in f]


archived = set()
for p in sorted(glob.glob(".ai-log/archive/*.jsonl")):
    for ln in read_lines(p):
        if ln.strip():
            archived.add(h(ln))

raw = read_lines(LOG)
kept, seen = [], set()
dropped_archived = dropped_dup = 0
for ln in raw:
    if not ln.strip() or ln.startswith(MARKERS):
        continue
    k = h(ln)
    if k in archived:
        dropped_archived += 1
        continue
    if k in seen:
        dropped_dup += 1
        continue
    seen.add(k)
    kept.append(ln)


def ts(line):
    try:
        return json.loads(line).get("ts", "")
    except Exception:
        return ""


kept.sort(key=ts)

tmp = LOG + ".resolved.tmp"
with io.open(tmp, "w", encoding="utf-8", newline="\n") as f:
    for ln in kept:
        f.write(ln + "\n")
os.replace(tmp, LOG)

print(f"input lines (excl. markers): {sum(1 for l in raw if l.strip() and not l.startswith(MARKERS))}")
print(f"dropped already-archived   : {dropped_archived}")
print(f"dropped exact duplicates   : {dropped_dup}")
print(f"kept                       : {len(kept)}")
by = {}
for ln in kept:
    try:
        d = json.loads(ln)
        by.setdefault((d.get("ts", "")[:10], d.get("student", "?")), 0)
        by[(d.get("ts", "")[:10], d.get("student", "?"))] += 1
    except Exception:
        by.setdefault(("UNPARSEABLE", "?"), 0)
        by[("UNPARSEABLE", "?")] += 1
for k in sorted(by):
    print("  ", k[0], k[1], by[k])

